import { test, expect } from '@playwright/test';

test.describe('Click Target Accessibility - 44x44px Minimum Size', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <!DOCTYPE html>
      <html>
      <head>
        <style>
          body { margin: 20px; font-family: Arial, sans-serif; }
          .button-container { margin: 20px 0; }
          .small-button { width: 30px; height: 30px; padding: 0; }
          .compliant-button { width: 44px; height: 44px; padding: 0; }
          .large-button { width: 60px; height: 60px; padding: 0; }
          button { cursor: pointer; border: 1px solid #ccc; }
          a { display: inline-block; text-decoration: none; }
          .small-link { width: 30px; height: 30px; }
          .compliant-link { width: 44px; height: 44px; }
          .icon-button { display: inline-flex; align-items: center; justify-content: center; }
        </style>
      </head>
      <body>
        <h1>Click Target Size Accessibility Test</h1>

        <div class="button-container">
          <h2>Non-Compliant Targets (Below 44x44px)</h2>
          <button class="small-button icon-button" id="small-button" aria-label="Small button">×</button>
          <a href="#" class="small-link icon-button" id="small-link" aria-label="Small link">→</a>
        </div>

        <div class="button-container">
          <h2>Compliant Targets (44x44px)</h2>
          <button class="compliant-button icon-button" id="compliant-button" aria-label="Compliant button">✓</button>
          <a href="#" class="compliant-link icon-button" id="compliant-link" aria-label="Compliant link">✓</a>
        </div>

        <div class="button-container">
          <h2>Exceeds Minimum (60x60px)</h2>
          <button class="large-button icon-button" id="large-button" aria-label="Large button">+</button>
        </div>

        <div class="button-container">
          <h2>Text Buttons</h2>
          <button id="text-button-small" style="padding: 2px 4px;">Small</button>
          <button id="text-button-compliant" style="padding: 10px 15px;">Compliant Button</button>
        </div>
      </body>
      </html>
    `);
  });

  test('should identify non-compliant click targets below 44x44px', async ({ page }) => {
    const smallButton = page.getByLabel('Small button');
    const smallLink = page.getByLabel('Small link');

    const smallButtonBox = await smallButton.boundingBox();
    const smallLinkBox = await smallLink.boundingBox();

    expect(smallButtonBox).not.toBeNull();
    expect(smallLinkBox).not.toBeNull();

    if (smallButtonBox) {
      expect(smallButtonBox.width).toBeLessThan(44);
      expect(smallButtonBox.height).toBeLessThan(44);
    }

    if (smallLinkBox) {
      expect(smallLinkBox.width).toBeLessThan(44);
      expect(smallLinkBox.height).toBeLessThan(44);
    }
  });

  test('should verify compliant click targets meet 44x44px minimum', async ({ page }) => {
    const compliantButton = page.getByLabel('Compliant button');
    const compliantLink = page.getByLabel('Compliant link');

    const compliantButtonBox = await compliantButton.boundingBox();
    const compliantLinkBox = await compliantLink.boundingBox();

    expect(compliantButtonBox).not.toBeNull();
    expect(compliantLinkBox).not.toBeNull();

    if (compliantButtonBox) {
      expect(compliantButtonBox.width).toBeGreaterThanOrEqual(44);
      expect(compliantButtonBox.height).toBeGreaterThanOrEqual(44);
    }

    if (compliantLinkBox) {
      expect(compliantLinkBox.width).toBeGreaterThanOrEqual(44);
      expect(compliantLinkBox.height).toBeGreaterThanOrEqual(44);
    }
  });

  test('should verify large click targets exceed minimum size', async ({ page }) => {
    const largeButton = page.getByLabel('Large button');

    const largeButtonBox = await largeButton.boundingBox();

    expect(largeButtonBox).not.toBeNull();

    if (largeButtonBox) {
      expect(largeButtonBox.width).toBeGreaterThanOrEqual(44);
      expect(largeButtonBox.height).toBeGreaterThanOrEqual(44);
      expect(largeButtonBox.width).toBeGreaterThan(44);
      expect(largeButtonBox.height).toBeGreaterThan(44);
    }
  });

  test('should ensure text buttons have adequate click target size', async ({ page }) => {
    const compliantTextButton = page.getByRole('button', { name: 'Compliant Button' });

    const buttonBox = await compliantTextButton.boundingBox();

    expect(buttonBox).not.toBeNull();

    if (buttonBox) {
      expect(buttonBox.width).toBeGreaterThanOrEqual(44);
      expect(buttonBox.height).toBeGreaterThanOrEqual(44);
    }
  });

  test('should allow interaction with compliant-sized targets', async ({ page }) => {
    const compliantButton = page.getByLabel('Compliant button');

    await expect(compliantButton).toBeVisible();
    await expect(compliantButton).toBeEnabled();

    await compliantButton.click();

    await expect(compliantButton).toBeFocused();
  });

  test('should verify multiple interactive elements meet minimum size requirements', async ({ page }) => {
    const buttons = page.getByRole('button');
    const count = await buttons.count();

    expect(count).toBeGreaterThan(0);

    for (let i = 0; i < count; i++) {
      const button = buttons.nth(i);
      const box = await button.boundingBox();

      if (box) {
        const meetsMinimum = box.width >= 44 && box.height >= 44;
        const buttonText = await button.textContent();

        if (buttonText && buttonText.trim().length > 0) {
          expect(meetsMinimum).toBeTruthy();
        }
      }
    }
  });
});
